messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Car Race</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #000; }
        canvas { display: block; }
    </style>
</head>
<body>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Configuration ---
        const TRACK_LENGTH = 100;
        const RACE_DURATION = 12; // seconds
        const CAR_SPEED = 0.05; // visual speed multiplier for position updates

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue
        scene.fog = new THREE.Fog(0x87CEEB, 20, 150);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 200);
        camera.position.set(0, 12, -15);
        camera.lookAt(0, 0, 30);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
        dirLight.position.set(10, 20, -10);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        scene.add(dirLight);

        // --- Environment ---

        // Ground
        const groundGeo = new THREE.PlaneGeometry(200, 200);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x44aa44, roughness: 1 });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Track
        const trackGeo = new THREE.PlaneGeometry(12, TRACK_LENGTH + 20);
        const trackMat = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.8 });
        const track = new THREE.Mesh(trackGeo, trackMat);
        track.rotation.x = -Math.PI / 2;
        track.position.z = TRACK_LENGTH / 2;
        track.receiveShadow = true;
        scene.add(track);

        // Finish Line
        const finishGeo = new THREE.PlaneGeometry(12, 2);
        const finishMat = new THREE.MeshStandardMaterial({ color: 0xffffff });
        const finishLine = new THREE.Mesh(finishGeo, finishMat);
        finishLine.rotation.x = -Math.PI / 2;
        finishLine.position.set(0, 0.01, TRACK_LENGTH);
        finishLine.receiveShadow = true;
        scene.add(finishLine);

        // Finish Banner
        const bannerGeo = new THREE.BoxGeometry(12, 4, 0.5);
        const bannerMat = new THREE.MeshStandardMaterial({ color: 0x222222 });
        const banner = new THREE.Mesh(bannerGeo, bannerMat);
        banner.position.set(0, 2, TRACK_LENGTH);
        banner.castShadow = true;
        scene.add(banner);

        // --- Car Factory ---

        function createCar(colorHex) {
            const carGroup = new THREE.Group();

            // Body
            const bodyGeo = new THREE.BoxGeometry(2, 0.8, 4.5);
            const bodyMat = new THREE.MeshStandardMaterial({ color: colorHex, metalness: 0.6, roughness: 0.2 });
            const body = new THREE.Mesh(bodyGeo, bodyMat);
            body.position.y = 0.6;
            body.castShadow = true;
            carGroup.add(body);

            // Cabin
            const cabinGeo = new THREE.BoxGeometry(1.6, 0.6, 2);
            const cabinMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
            const cabin = new THREE.Mesh(cabinGeo, cabinMat);
            cabin.position.set(0, 1.3, -0.2);
            cabin.castShadow = true;
            carGroup.add(cabin);

            // Spoiler
            const spoilerGeo = new THREE.BoxGeometry(2.2, 0.1, 0.8);
            const spoiler = new THREE.Mesh(spoilerGeo, bodyMat);
            spoiler.position.set(0, 1.4, 2);
            carGroup.add(spoiler);

            const spoilerLegsGeo = new THREE.BoxGeometry(0.1, 0.4, 0.1);
            const leg1 = new THREE.Mesh(spoilerLegsGeo, bodyMat);
            leg1.position.set(0.8, 1.2, 2);
            carGroup.add(leg1);
            const leg2 = new THREE.Mesh(spoilerLegsGeo, bodyMat);
            leg2.position.set(-0.8, 1.2, 2);
            carGroup.add(leg2);

            // Wheels
            const wheelGeo = new THREE.CylinderGeometry(0.4, 0.4, 0.4, 16);
            const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111 });
            wheelGeo.rotateZ(Math.PI / 2);

            const positions = [
                { x: -1.1, z: -1.5 }, { x: 1.1, z: -1.5 },
                { x: -1.1, z: 1.5 }, { x: 1.1, z: 1.5 }
            ];

            positions.forEach(pos => {
                const wheel = new THREE.Mesh(wheelGeo, wheelMat);
                wheel.position.set(pos.x, 0.4, pos.z);
                wheel.castShadow = true;
                carGroup.add(wheel);
            });

            return carGroup;
        }

        const redCar = createCar(0xff0000);
        const blueCar = createCar(0x0000ff);

        // Initial positions
        redCar.position.set(-2, 0, 0);
        blueCar.position.set(2, 0, 0);

        scene.add(redCar);
        scene.add(blueCar);

        // --- Animation Logic ---

        const clock = new THREE.Clock();

        // Helper to normalize time for looping
        function getTime() {
            return clock.getElapsedTime();
        }

        // Helper for easing: Blue starts fast, Red starts slow then accelerates
        function getPosition(time, isRed) {
            const t = time % RACE_DURATION;
            let progress = t / RACE_DURATION;

            // Normalize to 0-1 range for bezier logic
            let p = progress;

            if (isRed) {
                // Red Car: Starts slow (low initial derivative), ends fast
                // Custom bezier approx: y = 3x^2 - 2x^3 (Ease In)
                // We want it to really accelerate late, so maybe a steeper curve
                // y = x^3 ? No, let's just use a standard ease-in but offset start slightly
                // Actually, let's just hardcode a curve where it falls behind then catches up.
                // Simple logic: position = base + acceleration * t^2
                // To ensure loop: at t=0, pos=0. At t=1, pos=1.
                // Red: x = 3t^2 - 2t^3
                return p * p * (3 - 2 * p); 
            } else {
                // Blue Car: Starts fast, slows down slightly to let Red pass?
                // Or just standard ease out? 
                // Requirement: Blue leads early, Red overtakes mid, Red wins.
                // If Red is Ease In, Blue should be Ease Out or Linear.
                // If Blue is Ease Out (1 - (1-t)^3), it starts fast and slows.
                // Red (3t^2 - 2t^3) starts slow.
                // Intersection check: 3t^2 - 2t^3 = 1 - (1-t)^3
                // 3t^2 - 2t^3 = 1 - (1 - 3t + 3t^2 - t^3) = 3t - 3t^2 + t^3
                // 2t^3 - 6t^2 + 3t = 0
                // t(2t^2 - 6t + 3) = 0
                // t = 0, or t = (6 +/- sqrt(36 - 24))/4 = (6 +/- 3.46)/4
                // t1 = 2.26 (invalid), t2 = 0.63.
                // So Red overtakes Blue at 63% of the track. Perfect.
                return 1 - Math.pow(1 - p, 3);
            }
        }

        // --- Render Loop ---

        function animate() {
            requestAnimationFrame(animate);

            const time = getTime();
            const loopTime = time % RACE_DURATION;

            // Calculate positions based on race progress (0 to 1)
            const redProgress = getPosition(loopTime, true);
            const blueProgress = getPosition(loopTime, false);

            // Map progress to track coordinates
            // Start at 0, End at TRACK_LENGTH
            const redZ = redProgress * TRACK_LENGTH;
            const blueZ = blueProgress * TRACK_LENGTH;

            redCar.position.z = redZ;
            blueCar.position.z = blueZ;

            // Add slight rotation for visual flair
            redCar.rotation.y = Math.sin(loopTime * 2) * 0.1;
            blueCar.rotation.y = Math.sin(loopTime * 2 + 1) * 0.1;

            // Camera Logic
            // Camera tracks the leading car mostly, but keeps both in view
            const leaderZ = Math.max(redZ, blueZ);
            const trailerZ = Math.min(redZ, blueZ);

            // Target position is behind the leader, adjusted by the gap
            // We want the camera to look ahead at the finish line mostly, but pan with the race
            const cameraTargetZ = leaderZ - 15;

            // Smooth camera movement
            camera.position.z += (cameraTargetZ - camera.position.z) * 0.05;
            camera.position.y += ((12 + (leaderZ/TRACK_LENGTH)*5) - camera.position.y) * 0.05;

            // Look at a point between the cars, slightly ahead
            const lookAtZ = (leaderZ + trailerZ) / 2 + 10;
            camera.lookAt(0, 0, lookAtZ);

            renderer.render(scene, camera);
        }

        // --- Resize Handler ---
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();

    </script>
</body>
</html>
```
